ECO_st.name='ECO'; 
ECO_st.lat=40.20;
ECO_st.lon=18.07;
ECO_st.alt=50;
ECO_st.env='Coast';
ECO_st.footp='U';
%%

% ECO_rd imported via impoart tool

ECO_rd_h.Properties.VariableNames{2}='BaR_Amaap';
ECO_rd_h.Properties.DimensionNames{1}='Time';
ECO_rd=retime(ECO_rd_h,'daily',@nanmedian);
names_rd=fieldnames(ECO_rd);
%%
datevec(ECO_rd.Time(1)) % begin in 2015 %[output:6f1d7b08]
datevec(ECO_rd.Time(end)) % end in 2025 %[output:74ffc91d]
% % prctile(ECO_rd.U1_S11,[5 50 95]) % < 30%, ok. 
% % prctile(ECO_rd.U0_S11,[5 50 95])
plotFigControl(ECO_rd,ECO_st.name); %[output:8ca27a12]
%%
% BP detection for scat coef and backscat

names_abs={'BaR_Amaap'};
break_ECO_abs_BP=change_point_analysis_Def(ECO_rd,names_abs,0.05,'ECO','Absorption MAAP'); %[output:187ac685] %[output:2e907980]
T_ECO_abs_BP=make_table_breakpoints_def(break_ECO_abs_BP);
%%
% use MAAP data as it, 
%recompute trend after answer if AE or 2025 are available
ECO_tr=ECO_rd;
ECO_tr.eBC__g_m3_=[];
%convert in Mm
ECO_tr.BaR_Amaap=ECO_tr.BaR_Amaap*1e6;
%%
[ECO_result_MK,ECO_result_LMSlog,ECO_result_LMSlin]=all_trend_STN(ECO_tr,ECO_st); %[output:145043e3] %[output:39266fb7] %[output:87a16912] %[output:47833741] %[output:2404a275]

writetable(ECO_result_MK,'ECO_res_MK.txt'); %, 'delimiter',',' )
writetable(ECO_result_LMSlog,'ECO_res_LMSlog.txt'); 
writetable(ECO_result_LMSlin,'ECO_res_LMSlin.txt'); 
plot_10y_in_two(ECO_result_MK, ECO_st,'y'); %[output:540ed6e4]

